-- GENERATED by scripts/build-setup-sql.mjs from supabase/migrations. Do not edit by hand.
-- Installs the whole schema in one go. For a project that had the old CountyConnect schema, run reset-connect.sql first.
-- Run in a fresh SQL editor tab; it is safe to run once, and will stop with an error if anything already exists.

-- ==== 20260930000100_reference.sql ====

-- County Yangu + CountyConnect: one database per county.
-- 0001  Reference data: county config, wards, departments, report categories, holidays.
--
-- Conventions used throughout the schema:
--  * RLS is enabled on every table. Anonymous visitors read curated views/reference
--    tables only. Every public write (report, vote, alert signup) goes through an
--    Edge Function that validates, rate-limits, hashes and then writes with the
--    service role. There are deliberately no anon/authenticated INSERT policies.
--  * Helper functions live in the `private` schema, which PostgREST does not expose.
--  * Every SECURITY DEFINER function pins search_path to '' and qualifies names.

create schema if not exists private;
revoke all on schema private from public;

-- Supabase grants every new table/function in `public` to anon and authenticated by default.
-- Turn that off: in this schema every privilege is granted explicitly, next to the object it is for.
alter default privileges in schema public revoke all on tables    from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;
alter default privileges in schema public revoke all on functions from anon, authenticated;
-- The service role (used only by Edge Functions and the SQL editor) keeps full access to everything created from here on.
-- Stated explicitly so it holds even in a project whose `public` schema was dropped and recreated.
alter default privileges in schema public grant all on tables    to service_role;
alter default privileges in schema public grant all on sequences to service_role;
alter default privileges in schema public grant all on functions to service_role;
alter default privileges revoke execute on functions from public;
-- Helpers in `private` are needed by RLS policies evaluated as the caller; the schema is not exposed by the API.
alter default privileges in schema private grant execute on functions to authenticated, service_role;

-- One row: the county this database serves.
create table public.county (
  id             smallint primary key default 1 check (id = 1),
  slug           text not null,
  name           text not null,
  code           int  not null,
  centroid_lat   numeric(9,6),
  centroid_lng   numeric(9,6),
  bbox           numeric[],                 -- {minLng,minLat,maxLng,maxLat}
  paybill        text,
  ussd_code      text,
  sender_id      text,
  timezone       text not null default 'Africa/Nairobi',
  default_locale text not null default 'en' check (default_locale in ('en', 'sw')),
  settings       jsonb not null default '{}'::jsonb
);

create table public.sub_counties (
  id           text primary key,
  name         text not null unique,
  centroid_lat numeric(9,6),
  centroid_lng numeric(9,6),
  area_km2     numeric(10,2)
);

create table public.wards (
  id            text primary key,           -- slug, e.g. 'kileleshwa'
  code          int unique,                 -- IEBC/KNBS ward code
  name          text not null,
  sub_county_id text references public.sub_counties (id),
  constituency  text not null,
  geojson       jsonb,                      -- Polygon / MultiPolygon geometry (WGS84), null until boundaries are loaded
  centroid_lat  numeric(9,6),
  centroid_lng  numeric(9,6),
  bbox          numeric[],                  -- {minLng,minLat,maxLng,maxLat}
  population    int
);
create index wards_sub_county_idx on public.wards (sub_county_id);

create table public.departments (
  id      uuid primary key default gen_random_uuid(),
  code    text not null unique,
  name    text not null,
  name_sw text
);

-- Two timers per category: time to acknowledge and time to resolve.
-- Working-day timers skip weekends and rows in public.holidays.
create table public.report_categories (
  id                text primary key,
  name              text not null,
  name_sw           text,
  department_id     uuid references public.departments (id),
  ack_value         int  not null default 2,
  ack_unit          text not null default 'working_days' check (ack_unit in ('hours', 'working_days')),
  resolve_value     int  not null default 21,
  resolve_unit      text not null default 'working_days' check (resolve_unit in ('hours', 'working_days')),
  default_priority  text not null default 'normal' check (default_priority in ('low', 'normal', 'high', 'urgent')),
  sensitive         boolean not null default false,   -- integrity/finance: routed around the implicated department
  active            boolean not null default true,
  sort              int not null default 0
);

create table public.holidays (
  day  date primary key,
  name text not null
);

-- Adds n working days (Mon-Fri, not a holiday) to a timestamp, in the county timezone.
create function private.add_working_days(p_from timestamptz, p_days int)
returns timestamptz
language plpgsql
stable
set search_path = ''
as $$
declare
  tz  text := coalesce((select c.timezone from public.county c limit 1), 'Africa/Nairobi');
  d   timestamp := p_from at time zone tz;
  n   int := p_days;
begin
  while n > 0 loop
    d := d + interval '1 day';
    if extract(isodow from d) < 6
       and not exists (select 1 from public.holidays h where h.day = d::date) then
      n := n - 1;
    end if;
  end loop;
  return d at time zone tz;
end;
$$;

create function private.add_sla(p_from timestamptz, p_value int, p_unit text)
returns timestamptz
language sql
stable
set search_path = ''
as $$
  select case p_unit
    when 'hours' then p_from + make_interval(hours => p_value)
    else private.add_working_days(p_from, p_value)
  end;
$$;

alter table public.county            enable row level security;
alter table public.sub_counties      enable row level security;
alter table public.wards             enable row level security;
alter table public.departments       enable row level security;
alter table public.report_categories enable row level security;
alter table public.holidays          enable row level security;

-- Reference data is public to read; only privileged staff write it (policies added in the identity migration).
create policy "reference is public" on public.county            for select to anon, authenticated using (true);
create policy "reference is public" on public.sub_counties      for select to anon, authenticated using (true);
create policy "reference is public" on public.wards             for select to anon, authenticated using (true);
create policy "reference is public" on public.departments       for select to anon, authenticated using (true);
create policy "reference is public" on public.report_categories for select to anon, authenticated using (active);
create policy "reference is public" on public.holidays          for select to anon, authenticated using (true);

grant select on public.county, public.sub_counties, public.wards, public.departments,
                public.report_categories, public.holidays to anon, authenticated;

-- ==== 20260930000200_identity.sql ====

-- 0002  Identity: profiles, scoped staff roles, auditor invites, role helpers.
--
-- Roles are NOT stored on the profile and can never come from signup metadata.
-- A role is a row in staff_roles, created only by an admin through grant_staff_role()
-- (or by a trusted database session when bootstrapping the first super admin).

create table public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  name       text not null default '',
  email      text,
  phone      text,
  national_id text,
  address    text,
  avatar_url text,
  ward_id    text references public.wards (id),
  locale     text not null default 'en' check (locale in ('en', 'sw')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Every new auth user gets a resident profile. Nothing in raw_user_meta_data can grant power.
create function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, name, email, phone)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'name', ''),
    new.email,
    coalesce(new.phone, new.raw_user_meta_data ->> 'phone_number')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

create table public.staff_roles (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  role          text not null check (role in (
                  'super_admin', 'admin', 'chief_officer', 'sub_county_admin',
                  'ward_admin', 'officer', 'assembly_member', 'auditor')),
  department_id uuid references public.departments (id),
  sub_county_id text references public.sub_counties (id),
  ward_id       text references public.wards (id),
  active        boolean not null default true,
  expires_at    timestamptz,                 -- auditors get time-limited access
  granted_by    uuid references auth.users (id),
  created_at    timestamptz not null default now(),
  -- scope must match the role
  constraint staff_roles_scope check (
    case role
      when 'chief_officer'     then department_id is not null
      when 'sub_county_admin'  then sub_county_id is not null
      when 'ward_admin'        then ward_id is not null
      else true
    end),
  unique nulls not distinct (user_id, role, department_id, sub_county_id, ward_id)
);
create index staff_roles_user_idx on public.staff_roles (user_id) where active;

create table public.auditor_invites (
  id          uuid primary key default gen_random_uuid(),
  token_hash  bytea not null unique,        -- sha-256 of the emailed token; the token itself is never stored
  email       text not null,
  organisation text,                        -- e.g. OAG, Controller of Budget
  expires_at  timestamptz not null,
  used_at     timestamptz,
  created_by  uuid references auth.users (id),
  created_at  timestamptz not null default now()
);

-- ---- helpers (private schema; not exposed through the API) -----------------

grant usage on schema private to authenticated, service_role;

-- Staff MFA. When the county sets settings.require_staff_mfa = true (at go-live), no staff permission
-- applies unless the session was authenticated with a second factor (JWT claim aal = 'aal2').
-- Residents are unaffected: this only gates rows in staff_roles. A user can still read their OWN role rows
-- (so the app can tell them to enrol an authenticator) but nothing else.
create function private.mfa_ok()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select c.settings ->> 'require_staff_mfa' from public.county c limit 1), 'false') <> 'true'
         or coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'aal', '') = 'aal2';
$$;

-- Does the signed-in user hold any active, unexpired role from the list?
create function private.has_role(p_roles text[])
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.staff_roles r
    where r.user_id = (select auth.uid())
      and private.mfa_ok()
      and r.active
      and (r.expires_at is null or r.expires_at > now())
      and r.role = any (p_roles)
  );
$$;

create function private.is_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.has_role(array['super_admin','admin','chief_officer','sub_county_admin',
                                'ward_admin','officer','assembly_member','auditor']);
$$;

create function private.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.has_role(array['super_admin','admin']);
$$;

-- Can the signed-in staff member act on a case in this ward / department / assignment?
-- Assembly members and auditors deliberately get NO row access here: they use the
-- oversight functions, which return summaries.
create function private.can_work_case(p_ward text, p_dept uuid, p_assignee uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.staff_roles r
    left join public.wards w on w.id = p_ward
    where r.user_id = (select auth.uid())
      and private.mfa_ok()
      and r.active
      and (r.expires_at is null or r.expires_at > now())
      and (
        r.role in ('super_admin', 'admin')
        or (r.role = 'chief_officer'    and r.department_id = p_dept)
        or (r.role = 'sub_county_admin' and r.sub_county_id = w.sub_county_id)
        or (r.role = 'ward_admin'       and r.ward_id = p_ward)
        or (r.role = 'officer'          and (p_assignee = r.user_id
                                             or (p_assignee is null and r.department_id = p_dept)))
      )
  );
$$;

-- ---- RLS + grants -----------------------------------------------------------

alter table public.profiles        enable row level security;
alter table public.staff_roles     enable row level security;
alter table public.auditor_invites enable row level security;

create policy "own profile: read"   on public.profiles for select to authenticated
  using ((select auth.uid()) = id or private.is_admin());
create policy "own profile: update" on public.profiles for update to authenticated
  using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

-- Users may edit personal details only. Nothing here can grant a role.
revoke all on public.profiles from anon, authenticated;
grant select on public.profiles to authenticated;
grant update (name, phone, national_id, address, avatar_url, ward_id, locale, updated_at)
  on public.profiles to authenticated;

-- staff_roles: read your own rows (the app needs them to route you); admins read all.
-- No INSERT/UPDATE/DELETE grants: use grant_staff_role() / revoke_staff_role().
create policy "own roles: read" on public.staff_roles for select to authenticated
  using ((select auth.uid()) = user_id or private.is_admin());
revoke all on public.staff_roles from anon, authenticated;
grant select on public.staff_roles to authenticated;

-- auditor_invites: admin only, via functions.
revoke all on public.auditor_invites from anon, authenticated;

-- Reference data is maintained by admins (edited through the console).
create policy "admins write" on public.county            for all to authenticated using (private.is_admin()) with check (private.is_admin());
create policy "admins write" on public.wards             for all to authenticated using (private.is_admin()) with check (private.is_admin());
create policy "admins write" on public.departments       for all to authenticated using (private.is_admin()) with check (private.is_admin());
create policy "admins write" on public.report_categories for all to authenticated using (private.is_admin()) with check (private.is_admin());
create policy "admins write" on public.holidays          for all to authenticated using (private.is_admin()) with check (private.is_admin());
create policy "admins write" on public.sub_counties      for all to authenticated using (private.is_admin()) with check (private.is_admin());
grant insert, update, delete on public.county, public.wards, public.departments,
  public.report_categories, public.holidays, public.sub_counties to authenticated;

-- ---- role administration -----------------------------------------------------

-- Only a super admin can create another admin/super admin; an admin can grant operational roles.
create function public.grant_staff_role(
  p_user uuid,
  p_role text,
  p_department uuid default null,
  p_sub_county text default null,
  p_ward text default null,
  p_expires_at timestamptz default null
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_actor uuid := (select auth.uid());
begin
  -- v_actor is null for trusted sessions (SQL editor / service role bootstrap).
  if v_actor is not null then
    if p_role in ('super_admin', 'admin') then
      if not private.has_role(array['super_admin']) then
        raise exception 'Only a super admin can grant %', p_role using errcode = '42501';
      end if;
    elsif not private.is_admin() then
      raise exception 'Only an admin can grant staff roles' using errcode = '42501';
    end if;
  end if;

  insert into public.staff_roles (user_id, role, department_id, sub_county_id, ward_id, expires_at, granted_by)
  values (p_user, p_role, p_department, p_sub_county, p_ward, p_expires_at, v_actor)
  on conflict (user_id, role, department_id, sub_county_id, ward_id)
    do update set active = true, expires_at = excluded.expires_at, granted_by = excluded.granted_by
  returning id into v_id;
  return v_id;
end;
$$;

create function public.revoke_staff_role(p_role_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role text;
begin
  select role into v_role from public.staff_roles where id = p_role_id;
  if v_role is null then return; end if;
  if (select auth.uid()) is not null then
    if v_role in ('super_admin', 'admin') then
      if not private.has_role(array['super_admin']) then
        raise exception 'Only a super admin can revoke %', v_role using errcode = '42501';
      end if;
    elsif not private.is_admin() then
      raise exception 'Only an admin can revoke staff roles' using errcode = '42501';
    end if;
  end if;
  update public.staff_roles set active = false where id = p_role_id;
end;
$$;

grant execute on function public.grant_staff_role(uuid, text, uuid, text, text, timestamptz) to authenticated, service_role;
grant execute on function public.revoke_staff_role(uuid) to authenticated, service_role;

-- ==== 20260930000300_civic.sql ====

-- 0003  Civic data: cases (reports), projects, participatory budget, tenders, proposals, alerts.
--
-- Anonymity rules:
--  * reports carry NO reporter identity. An optional callback number lives in
--    private.report_contacts, keyed by report id, and is never joined to votes.
--  * votes carry only a keyed hash of the phone number (HMAC with a county secret,
--    computed in the Edge Function). Votes and reports never share a key.

-- ---- contractors, projects ---------------------------------------------------

create table public.contractors (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  registration_no text,
  kra_pin       text,
  kra_compliant boolean,                    -- last GavaConnect check result
  kra_checked_at timestamptz,
  flags         text[] not null default '{}',
  created_at    timestamptz not null default now()
);

create table public.tenders (
  id                    uuid primary key default gen_random_uuid(),
  reference             text not null unique,
  title                 text not null,
  ward_id               text references public.wards (id),
  sector                text not null,
  status                text not null default 'open' check (status in ('draft', 'open', 'evaluating', 'awarded', 'cancelled')),
  estimated_budget      numeric(16, 2) not null check (estimated_budget >= 0),
  applicants_count      int not null default 0,
  awarded_contractor_id uuid references public.contractors (id),
  published_at          timestamptz,
  closes_at             timestamptz,
  created_by            uuid references auth.users (id),
  created_at            timestamptz not null default now()
);

create table public.projects (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,
  ward_id       text not null references public.wards (id),
  title         text not null,
  sector        text not null,
  description   text,
  status        text not null default 'planned' check (status in ('planned', 'procurement', 'in_progress', 'stalled', 'completed')),
  budget        numeric(16, 2) not null check (budget >= 0),
  spent         numeric(16, 2) not null default 0 check (spent >= 0),
  contractor_id uuid references public.contractors (id),
  tender_id     uuid references public.tenders (id),
  lat           numeric(9, 6),
  lng           numeric(9, 6),
  started_at    date,
  expected_at   date,
  completed_at  date,
  published     boolean not null default false,
  created_by    uuid references auth.users (id),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index projects_ward_idx on public.projects (ward_id);
create index projects_status_idx on public.projects (status);

create table public.project_milestones (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null references public.projects (id) on delete cascade,
  title        text not null,
  due_date     date,
  completed_at date,
  sort         int not null default 0
);
create index project_milestones_project_idx on public.project_milestones (project_id);

create table public.project_photos (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null references public.projects (id) on delete cascade,
  storage_path text not null,
  caption      text,
  taken_at     timestamptz,
  created_at   timestamptz not null default now()
);
create index project_photos_project_idx on public.project_photos (project_id);

-- ---- participatory budget ----------------------------------------------------

create table public.budget_cycles (
  id        text primary key,
  title     text not null,
  status    text not null default 'draft' check (status in ('draft', 'open', 'closed')),
  starts_at timestamptz not null,
  ends_at   timestamptz not null,
  published_results boolean not null default false,
  check (ends_at > starts_at)
);

create table public.ward_budget_envelopes (
  cycle_id text not null references public.budget_cycles (id) on delete cascade,
  ward_id  text not null references public.wards (id) on delete cascade,
  amount   numeric(16, 2) not null check (amount >= 0),
  primary key (cycle_id, ward_id)
);

create table public.project_options (
  id        text primary key,
  cycle_id  text not null references public.budget_cycles (id) on delete cascade,
  ward_id   text not null references public.wards (id) on delete cascade,
  title     text not null,
  sector    text not null,
  description text,
  amount    numeric(16, 2) not null check (amount >= 0)
);
create index project_options_cycle_ward_idx on public.project_options (cycle_id, ward_id);

-- One vote per verified phone per cycle. voter_hash = HMAC(county secret, cycle || msisdn).
create table public.votes (
  id         uuid primary key default gen_random_uuid(),
  cycle_id   text not null references public.budget_cycles (id) on delete cascade,
  ward_id    text not null references public.wards (id),
  option_id  text not null references public.project_options (id),
  channel    text not null check (channel in ('web', 'ussd', 'ivr', 'sms')),
  voter_hash bytea not null,
  created_at timestamptz not null default now(),
  unique (cycle_id, voter_hash)
);

-- ---- cases (citizen reports) -------------------------------------------------

-- Case references are unguessable enough to act as a bearer token for the public
-- status page: 3-letter county prefix + 10 hex chars (40 bits) from a CSPRNG.
create function private.new_reference(p_kind text default 'R')
returns text
language sql
volatile
set search_path = ''
as $$
  select upper(coalesce(substr((select c.slug from public.county c limit 1), 1, 3), 'CTY'))
         || '-' || p_kind || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
$$;

create table public.reports (
  id               uuid primary key default gen_random_uuid(),
  reference        text not null unique default private.new_reference('R'),
  client_key       uuid unique,                         -- idempotency key from the offline queue
  ward_id          text not null references public.wards (id),
  category_id      text references public.report_categories (id),
  department_id    uuid references public.departments (id),
  description      text not null check (char_length(description) between 5 and 2000),  -- personal details already scrubbed
  status           text not null default 'received' check (status in ('received', 'triaged', 'assigned', 'in_progress', 'resolved', 'closed', 'rejected')),
  priority         text not null default 'normal' check (priority in ('low', 'normal', 'high', 'urgent')),
  channel          text not null default 'web' check (channel in ('web', 'ussd', 'sms', 'ivr', 'voice')),
  language         text,
  lat              numeric(9, 6),
  lng              numeric(9, 6),
  assigned_to      uuid references auth.users (id),
  project_id       uuid references public.projects (id),
  duplicate_of     uuid references public.reports (id),
  flagged_financial boolean not null default false,     -- set by rules/AI; reviewable by staff
  ack_due_at       timestamptz,
  resolve_due_at   timestamptz,
  acknowledged_at  timestamptz,
  resolved_at      timestamptz,
  escalation_level smallint not null default 0,         -- 0 none, 1 reminder, 2 sub-county, 3 chief officer, 4 CEC/assembly, 5 oversight digest
  last_escalated_at timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index reports_ward_idx        on public.reports (ward_id);
create index reports_status_idx      on public.reports (status) where status not in ('resolved', 'closed', 'rejected');
create index reports_assignee_idx    on public.reports (assigned_to);
create index reports_dept_idx        on public.reports (department_id);
create index reports_resolve_due_idx on public.reports (resolve_due_at) where status not in ('resolved', 'closed', 'rejected');

create table public.report_photos (
  id           uuid primary key default gen_random_uuid(),
  report_id    uuid not null references public.reports (id) on delete cascade,
  storage_path text not null,
  created_at   timestamptz not null default now()
);
create index report_photos_report_idx on public.report_photos (report_id);

-- Timeline. `public` rows (with a public message) are visible on the case-status page.
create table public.report_events (
  id         uuid primary key default gen_random_uuid(),
  report_id  uuid not null references public.reports (id) on delete cascade,
  kind       text not null check (kind in ('created', 'triaged', 'assigned', 'status', 'note', 'public_message', 'reminder', 'escalated', 'merged')),
  actor_id   uuid references auth.users (id),           -- null = system
  is_public  boolean not null default false,
  message    text,
  data       jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index report_events_report_idx on public.report_events (report_id, created_at);

-- Routing matrix (admin-editable): category x ward -> department / officer.
-- The most specific matching row wins (ward-specific before county-wide).
create table public.routing_rules (
  id            uuid primary key default gen_random_uuid(),
  category_id   text not null references public.report_categories (id) on delete cascade,
  ward_id       text references public.wards (id) on delete cascade,   -- null = whole county
  department_id uuid not null references public.departments (id),
  officer_id    uuid references auth.users (id),
  created_at    timestamptz not null default now(),
  unique nulls not distinct (category_id, ward_id)
);

-- ---- proposals / petitions ---------------------------------------------------

create table public.proposals (
  id          uuid primary key default gen_random_uuid(),
  ward_id     text references public.wards (id),        -- null = county-wide
  kind        text not null default 'proposal' check (kind in ('proposal', 'petition')),
  title       text not null check (char_length(title) between 5 and 160),
  body        text not null check (char_length(body) between 10 and 4000),
  status      text not null default 'submitted' check (status in ('submitted', 'under_review', 'accepted', 'declined', 'merged')),
  response    text,
  responded_by uuid references auth.users (id),
  cluster_id  uuid references public.proposals (id),
  supporters  int not null default 0,
  created_at  timestamptz not null default now()
);

create table public.proposal_supports (
  proposal_id uuid not null references public.proposals (id) on delete cascade,
  voter_hash  bytea not null,
  created_at  timestamptz not null default now(),
  primary key (proposal_id, voter_hash)
);

-- Keep the supporter count exact and cheap to read.
create function private.bump_supporters()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.proposals set supporters = supporters + 1 where id = new.proposal_id;
  return new;
end;
$$;
create trigger proposal_supports_count
  after insert on public.proposal_supports
  for each row execute function private.bump_supporters();

-- ---- ward alerts (staff compose -> a second person approves -> send) ---------

create table public.alerts (
  id          uuid primary key default gen_random_uuid(),
  ward_id     text references public.wards (id),        -- null = county-wide
  title       text not null,
  body        text not null check (char_length(body) <= 480),
  status      text not null default 'draft' check (status in ('draft', 'pending_approval', 'approved', 'sent', 'cancelled')),
  created_by  uuid not null references auth.users (id),
  approved_by uuid references auth.users (id),
  approved_at timestamptz,
  sent_at     timestamptz,
  recipients  int,
  created_at  timestamptz not null default now(),
  check (approved_by is null or approved_by <> created_by)   -- four eyes
);

-- ---- private tables (never exposed through the API) --------------------------

-- Optional, opt-in callback number for a report. Consent is explicit and recorded.
create table private.report_contacts (
  report_id  uuid primary key references public.reports (id) on delete cascade,
  phone_e164 text not null,
  consented_at timestamptz not null default now()
);

-- SMS alert subscribers (the number itself is needed to send).
create table private.subscribers (
  id          uuid primary key default gen_random_uuid(),
  phone_e164  text not null,
  ward_id     text not null references public.wards (id),
  channel     text not null default 'sms' check (channel in ('sms', 'whatsapp', 'push')),
  frequency   text not null default 'weekly' check (frequency in ('instant', 'daily', 'weekly')),
  verified_at timestamptz,
  opted_out_at timestamptz,
  created_at  timestamptz not null default now(),
  unique (phone_e164, ward_id)
);

-- One-time codes for phone verification. Only a hash of the code is stored.
create table private.otp_codes (
  id         uuid primary key default gen_random_uuid(),
  phone_hash bytea not null,
  phone_e164 text not null,
  code_hash  bytea not null,
  purpose    text not null check (purpose in ('vote', 'alerts', 'petition', 'login')),
  attempts   int not null default 0,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);
create index otp_codes_phone_idx on private.otp_codes (phone_hash, created_at desc);

-- Sliding-window counters for abuse control (SMS pumping, spam).
create table private.rate_limits (
  key          text not null,
  window_start timestamptz not null,
  hits         int not null default 0,
  primary key (key, window_start)
);

-- Outgoing messages. The send function drains this table.
create table private.outbox (
  id         uuid primary key default gen_random_uuid(),
  channel    text not null check (channel in ('sms', 'email', 'push')),
  recipient  text not null,
  subject    text,
  body       text not null,
  status     text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed')),
  attempts   int not null default 0,
  last_error text,
  run_after  timestamptz not null default now(),
  related    jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  sent_at    timestamptz
);
create index outbox_due_idx on private.outbox (run_after) where status = 'queued';

-- Fixed-window rate limiter used by the Edge Functions (service role).
create function private.rate_limit_hit(p_key text, p_window_seconds int, p_max int)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_window timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_hits int;
begin
  insert into private.rate_limits (key, window_start, hits)
  values (p_key, v_window, 1)
  on conflict (key, window_start) do update set hits = private.rate_limits.hits + 1
  returning hits into v_hits;
  -- opportunistic cleanup
  delete from private.rate_limits where window_start < now() - interval '2 days';
  return v_hits <= p_max;
end;
$$;
revoke execute on function private.rate_limit_hit(text, int, int) from authenticated;
grant execute on function private.rate_limit_hit(text, int, int) to service_role;

grant usage on schema private to service_role;
grant all on all tables in schema private to service_role;

-- ==== 20260930000400_services.sql ====

-- 0004  My Services: catalogue, applications, payments, revenue, notifications.
-- (Ported from CountyConnect's citizen screens, with real keys instead of free text.)

create table public.services (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,
  name          text not null,
  name_sw       text,
  department_id uuid references public.departments (id),
  category      text not null default 'permit' check (category in ('permit', 'licence', 'rates', 'welfare', 'planning', 'health', 'other')),
  description   text,
  fee           numeric(14, 2) not null default 0 check (fee >= 0),
  fee_note      text,
  requires_kra_pin boolean not null default false,       -- checked through GavaConnect before submission
  form_schema   jsonb not null default '[]'::jsonb,      -- ordered field definitions rendered by the app
  required_documents text[] not null default '{}',
  sla_working_days int not null default 14,
  status        text not null default 'draft' check (status in ('draft', 'active', 'suspended')),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table public.applications (
  id            uuid primary key default gen_random_uuid(),
  reference     text not null unique default private.new_reference('A'),
  service_id    uuid not null references public.services (id),
  applicant_id  uuid not null references auth.users (id),
  ward_id       text references public.wards (id),
  business_name text,
  kra_pin       text,
  form_data     jsonb not null default '{}'::jsonb,
  status        text not null default 'draft' check (status in (
                  'draft', 'awaiting_payment', 'submitted', 'under_review',
                  'changes_requested', 'approved', 'rejected', 'withdrawn')),
  amount        numeric(14, 2) not null default 0 check (amount >= 0),   -- copied from the service fee by the server, never trusted from the client
  assigned_to   uuid references auth.users (id),
  decided_by    uuid references auth.users (id),
  decided_at    timestamptz,
  decision_note text,
  due_at        timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index applications_applicant_idx on public.applications (applicant_id);
create index applications_status_idx    on public.applications (status);
create index applications_service_idx   on public.applications (service_id);

create table public.application_documents (
  id             uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.applications (id) on delete cascade,
  kind           text not null,
  storage_path   text not null,
  created_at     timestamptz not null default now()
);
create index application_documents_app_idx on public.application_documents (application_id);

create table public.payments (
  id                  uuid primary key default gen_random_uuid(),
  checkout_request_id text unique,
  application_id      uuid references public.applications (id),
  payer_id            uuid references auth.users (id),
  phone_last4         text,                               -- the full MSISDN is not kept here
  amount              numeric(14, 2) not null check (amount > 0),
  status              text not null default 'pending' check (status in ('pending', 'completed', 'failed', 'timeout')),
  mpesa_receipt       text unique,
  stream              text not null default 'services',   -- revenue stream: services, land_rates, market_fees ...
  created_at          timestamptz not null default now(),
  completed_at        timestamptz
);
create index payments_application_idx on public.payments (application_id);

create table public.revenue_entries (
  id          uuid primary key default gen_random_uuid(),
  reference   text not null unique,                      -- M-Pesa receipt or bank reference
  amount      numeric(14, 2) not null check (amount > 0),
  payer_name  text,
  stream      text not null,
  source      text not null default 'mpesa' check (source in ('mpesa', 'cash', 'bank')),
  payment_id  uuid references public.payments (id),
  reconciled  boolean not null default false,
  received_at timestamptz not null default now()
);
create index revenue_entries_received_idx on public.revenue_entries (received_at);

create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  title      text not null,
  message    text not null,
  kind       text not null default 'info' check (kind in ('info', 'success', 'warning', 'error')),
  link       text,
  read       boolean not null default false,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);

-- The server, not the browser, decides what an application costs.
create function private.application_defaults()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_fee numeric;
  v_sla int;
begin
  if tg_op = 'INSERT' then
    select s.fee, s.sla_working_days into v_fee, v_sla from public.services s where s.id = new.service_id and s.status = 'active';
    if not found then
      raise exception 'Service is not available' using errcode = '22023';
    end if;
    new.amount := v_fee;
    new.due_at := private.add_working_days(now(), v_sla);
    new.status := 'draft';
  end if;
  new.updated_at := now();
  return new;
end;
$$;
create trigger applications_defaults
  before insert or update on public.applications
  for each row execute function private.application_defaults();

-- Applicants can never change price, owner, assignment or decision fields.
create function private.applications_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and not private.is_staff() then
    if new.amount is distinct from old.amount
       or new.applicant_id is distinct from old.applicant_id
       or new.service_id is distinct from old.service_id
       or new.assigned_to is distinct from old.assigned_to
       or new.decided_by is distinct from old.decided_by
       or new.decided_at is distinct from old.decided_at
       or new.decision_note is distinct from old.decision_note then
      raise exception 'Protected application fields cannot be changed' using errcode = '42501';
    end if;
    if new.status is distinct from old.status
       and not (old.status in ('draft', 'changes_requested') and new.status in ('draft', 'awaiting_payment', 'submitted', 'withdrawn')) then
      raise exception 'Invalid status change' using errcode = '42501';
    end if;
    -- a fee-bearing application cannot skip payment
    if new.status = 'submitted' and old.status <> 'submitted' and new.amount > 0
       and not exists (select 1 from public.payments p where p.application_id = new.id and p.status = 'completed') then
      raise exception 'Payment required before submission' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;
create trigger applications_guard_update
  before update on public.applications
  for each row execute function private.applications_guard();

-- Staff decision on an application (the only way status moves to approved/rejected).
create function public.decide_application(p_application uuid, p_decision text, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_app public.applications;
  v_dept uuid;
begin
  if p_decision not in ('approved', 'rejected', 'changes_requested', 'under_review') then
    raise exception 'Invalid decision %', p_decision using errcode = '22023';
  end if;
  select a.* into v_app from public.applications a where a.id = p_application;
  if not found then raise exception 'Application not found' using errcode = 'P0002'; end if;
  select s.department_id into v_dept from public.services s where s.id = v_app.service_id;

  if not (private.is_admin()
          or exists (select 1 from public.staff_roles r
                     where r.user_id = (select auth.uid()) and private.mfa_ok() and r.active
                       and (r.expires_at is null or r.expires_at > now())
                       and r.role in ('chief_officer', 'officer') and r.department_id = v_dept)) then
    raise exception 'Not allowed to decide this application' using errcode = '42501';
  end if;
  if v_app.status not in ('submitted', 'under_review', 'changes_requested') then
    raise exception 'Application is not awaiting a decision (status %)', v_app.status using errcode = '22023';
  end if;

  update public.applications
     set status = p_decision,
         decided_by = case when p_decision in ('approved', 'rejected') then (select auth.uid()) else decided_by end,
         decided_at = case when p_decision in ('approved', 'rejected') then now() else decided_at end,
         decision_note = coalesce(p_note, decision_note)
   where id = p_application;

  insert into public.notifications (user_id, title, message, kind, link)
  values (v_app.applicant_id,
          'Application ' || v_app.reference,
          case p_decision
            when 'approved' then 'Your application was approved.'
            when 'rejected' then 'Your application was not approved.' || coalesce(' ' || p_note, '')
            when 'changes_requested' then 'Changes are needed: ' || coalesce(p_note, 'see the application')
            else 'Your application is under review.'
          end,
          case p_decision when 'approved' then 'success' when 'rejected' then 'error' else 'info' end,
          '/services/applications/' || v_app.id);
end;
$$;
grant execute on function public.decide_application(uuid, text, text) to authenticated;

-- ==== 20260930000500_operations.sql ====

-- 0005  Operations: audit log, case workflow (SLA, routing, events, RPCs), escalation,
--       oversight, alerts approval, AI spend control, digests.

-- ---- audit log (append-only) -------------------------------------------------

create table public.audit_log (
  id         bigint generated always as identity primary key,
  at         timestamptz not null default now(),
  actor_id   uuid,                       -- null = system / service role
  via        text,                       -- jwt role at the time (authenticated, service_role, ...)
  action     text not null,              -- INSERT / UPDATE / DELETE
  entity     text not null,
  entity_id  text,
  before     jsonb,
  after      jsonb
);
create index audit_log_entity_idx on public.audit_log (entity, entity_id);
create index audit_log_actor_idx  on public.audit_log (actor_id, at desc);

create function private.audit_row()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  v_new jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
begin
  insert into public.audit_log (actor_id, via, action, entity, entity_id, before, after)
  values ((select auth.uid()),
          current_setting('request.jwt.claim.role', true),
          tg_op, tg_table_name,
          coalesce(v_new ->> 'id', v_old ->> 'id'),
          v_old, v_new);
  return coalesce(new, old);
end;
$$;

-- Nobody edits history: not staff, not admins, not the service role.
create function private.audit_immutable()
returns trigger
language plpgsql
as $$
begin
  raise exception 'audit_log is append-only' using errcode = '42501';
end;
$$;
create trigger audit_log_no_update before update or delete on public.audit_log
  for each row execute function private.audit_immutable();
create trigger audit_log_no_truncate before truncate on public.audit_log
  for each statement execute function private.audit_immutable();

do $$
declare t text;
begin
  foreach t in array array[
    'staff_roles', 'routing_rules', 'report_categories', 'services', 'applications',
    'projects', 'tenders', 'contractors', 'budget_cycles', 'alerts', 'proposals',
    'payments', 'revenue_entries', 'departments', 'wards'
  ] loop
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I
                    for each row execute function private.audit_row()', t);
  end loop;
end $$;

-- Reports are audited on updates/deletes only (inserts are the high-volume path and already
-- recorded as a `created` event on the case timeline).
create trigger audit_reports after update or delete on public.reports
  for each row execute function private.audit_row();

-- ---- case workflow ------------------------------------------------------------

-- On insert: route (matrix), set priority and both SLA timers, write the first event.
create function private.route_and_stamp_report()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cat public.report_categories;
  v_rule public.routing_rules;
begin
  if new.category_id is not null then
    select * into v_cat from public.report_categories where id = new.category_id;
    -- most specific rule wins: ward-specific before county-wide
    select * into v_rule from public.routing_rules
     where category_id = new.category_id and (ward_id = new.ward_id or ward_id is null)
     order by (ward_id is null) asc limit 1;
  end if;

  if v_cat.id is not null then
    new.priority       := coalesce(nullif(new.priority, 'normal'), v_cat.default_priority);
    new.ack_due_at     := coalesce(new.ack_due_at,     private.add_sla(new.created_at, v_cat.ack_value, v_cat.ack_unit));
    new.resolve_due_at := coalesce(new.resolve_due_at, private.add_sla(new.created_at, v_cat.resolve_value, v_cat.resolve_unit));
    -- sensitive (integrity/finance) categories are flagged for review and routed around the ordinary chain
    if v_cat.sensitive then new.flagged_financial := true; end if;
  end if;

  if v_rule.id is not null then
    new.department_id := coalesce(new.department_id, v_rule.department_id);
    new.assigned_to   := coalesce(new.assigned_to, v_rule.officer_id);
  elsif v_cat.department_id is not null then
    new.department_id := coalesce(new.department_id, v_cat.department_id);
  end if;

  if new.assigned_to is not null and new.status = 'received' then
    new.status := 'assigned';
  end if;
  return new;
end;
$$;
create trigger reports_route_before_insert
  before insert on public.reports
  for each row execute function private.route_and_stamp_report();

create function private.report_created_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.report_events (report_id, kind, is_public, message, data)
  values (new.id, 'created', true, 'Report received',
          jsonb_build_object('channel', new.channel, 'category', new.category_id));
  if new.assigned_to is not null then
    insert into public.report_events (report_id, kind, is_public, message, data)
    values (new.id, 'assigned', false, 'Routed by rule', jsonb_build_object('assigned_to', new.assigned_to));
  end if;
  return new;
end;
$$;
create trigger reports_after_insert_event
  after insert on public.reports
  for each row execute function private.report_created_event();

create function private.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
create trigger reports_touch before update on public.reports for each row execute function private.touch_updated_at();
create trigger projects_touch before update on public.projects for each row execute function private.touch_updated_at();
create trigger services_touch before update on public.services for each row execute function private.touch_updated_at();

-- Staff move a case along. Every call writes a timeline event; a public message
-- also reaches the reporter by SMS if they left a number.
create function public.case_transition(
  p_report uuid,
  p_status text,
  p_message text default null,
  p_public boolean default false
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r public.reports;
  v_phone text;
begin
  if p_status not in ('triaged', 'assigned', 'in_progress', 'resolved', 'closed', 'rejected') then
    raise exception 'Invalid status %', p_status using errcode = '22023';
  end if;
  select r.* into v_r from public.reports r where r.id = p_report for update;
  if not found then raise exception 'Case not found' using errcode = 'P0002'; end if;
  if not private.can_work_case(v_r.ward_id, v_r.department_id, v_r.assigned_to) then
    raise exception 'Not allowed to work this case' using errcode = '42501';
  end if;

  update public.reports
     set status = p_status,
         acknowledged_at = coalesce(acknowledged_at, now()),
         resolved_at = case when p_status in ('resolved', 'closed') then coalesce(resolved_at, now()) else resolved_at end
   where id = p_report;

  insert into public.report_events (report_id, kind, actor_id, is_public, message, data)
  values (p_report, 'status', (select auth.uid()), p_public, p_message, jsonb_build_object('status', p_status));

  if p_public then
    select c.phone_e164 into v_phone from private.report_contacts c where c.report_id = p_report;
    if v_phone is not null then
      insert into private.outbox (channel, recipient, body, related)
      values ('sms', v_phone,
              'County update ' || v_r.reference || ': ' || p_status || coalesce(' - ' || p_message, ''),
              jsonb_build_object('report_id', p_report));
    end if;
  end if;
end;
$$;

create function public.case_assign(p_report uuid, p_officer uuid, p_department uuid default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r public.reports;
begin
  select r.* into v_r from public.reports r where r.id = p_report for update;
  if not found then raise exception 'Case not found' using errcode = 'P0002'; end if;
  if not private.can_work_case(v_r.ward_id, v_r.department_id, v_r.assigned_to)
     or private.has_role(array['officer']) and not private.has_role(array['super_admin','admin','chief_officer','sub_county_admin','ward_admin']) then
    raise exception 'Not allowed to assign this case' using errcode = '42501';
  end if;
  update public.reports
     set assigned_to = p_officer,
         department_id = coalesce(p_department, department_id),
         status = case when status in ('received', 'triaged') then 'assigned' else status end
   where id = p_report;
  insert into public.report_events (report_id, kind, actor_id, message, data)
  values (p_report, 'assigned', (select auth.uid()), null,
          jsonb_build_object('assigned_to', p_officer, 'department_id', coalesce(p_department, v_r.department_id)));
end;
$$;

create function public.case_note(p_report uuid, p_message text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r public.reports;
begin
  select r.* into v_r from public.reports r where r.id = p_report;
  if not found then raise exception 'Case not found' using errcode = 'P0002'; end if;
  if not private.can_work_case(v_r.ward_id, v_r.department_id, v_r.assigned_to) then
    raise exception 'Not allowed to work this case' using errcode = '42501';
  end if;
  insert into public.report_events (report_id, kind, actor_id, is_public, message)
  values (p_report, 'note', (select auth.uid()), false, p_message);
end;
$$;

grant execute on function public.case_transition(uuid, text, text, boolean) to authenticated;
grant execute on function public.case_assign(uuid, uuid, uuid) to authenticated;
grant execute on function public.case_note(uuid, text) to authenticated;

-- The public status page: reveals only status, category, ward and public messages.
create function public.case_status(p_reference text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'reference', r.reference,
    'status', r.status,
    'category_id', r.category_id,
    'category', c.name,
    'category_sw', c.name_sw,
    'ward', w.name,
    'ward_id', r.ward_id,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'resolve_due_at', r.resolve_due_at,
    'project_slug', p.slug,
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('kind', e.kind, 'message', e.message, 'at', e.created_at) order by e.created_at)
      from public.report_events e where e.report_id = r.id and e.is_public), '[]'::jsonb))
  from public.reports r
  join public.wards w on w.id = r.ward_id
  left join public.report_categories c on c.id = r.category_id
  left join public.projects p on p.id = r.project_id and p.published
  where r.reference = upper(trim(p_reference));
$$;

-- ---- escalation ladder -----------------------------------------------------------
-- Rules decide who is told and when; nothing here calls a model.
--   level 1  acknowledgement overdue          -> reminder to officer + supervisor
--   level 2  5 working days unacknowledged    -> sub-county administrator
--   level 3  resolve target missed            -> chief officer (and the public overdue counter)
--   level 4  30 days past target              -> CEC member and Assembly committee (named in digest)
--   level 5  monthly digest to OAG / Controller of Budget carries every case still open
-- Called hourly by the escalation-runner Edge Function.

create function public.run_escalations()
returns table (report_id uuid, level smallint)
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.reports;
  v_target smallint;
  v_level smallint;
begin
  if (select auth.uid()) is not null and not private.is_admin() then
    raise exception 'Only the escalation runner may call this' using errcode = '42501';
  end if;

  for r in
    select * from public.reports
     where status not in ('resolved', 'closed', 'rejected')
       and duplicate_of is null
     for update skip locked
  loop
    v_target := 0;
    if r.acknowledged_at is null and r.ack_due_at is not null and now() > r.ack_due_at then v_target := 1; end if;
    if r.acknowledged_at is null and now() > private.add_working_days(r.created_at, 5) then v_target := 2; end if;
    if r.resolve_due_at is not null and now() > r.resolve_due_at then v_target := 3; end if;
    if r.resolve_due_at is not null and now() > r.resolve_due_at + interval '30 days' then v_target := 4; end if;

    if v_target > r.escalation_level then
      update public.reports set escalation_level = v_target, last_escalated_at = now() where id = r.id;
      -- One event per level crossed, so every rung of the ladder is notified and recorded even if the
      -- runner was down for a while and the case jumped several levels at once.
      for v_level in (r.escalation_level + 1)..v_target loop
        insert into public.report_events (report_id, kind, is_public, message, data)
        values (r.id, case when v_level = 1 then 'reminder' else 'escalated' end,
                v_level >= 3,   -- from level 3 the public sees that the case is overdue (never who holds it)
                case v_level
                  when 1 then 'Reminder sent: waiting to be acknowledged'
                  when 2 then 'Escalated to the sub-county administrator'
                  when 3 then 'Past its target date; escalated to the chief officer'
                  else 'Escalated to the CEC member and Assembly committee'
                end,
                jsonb_build_object('level', v_level));
        report_id := r.id; level := v_level; return next;
      end loop;
    end if;
  end loop;
end;
$$;
grant execute on function public.run_escalations() to service_role;

-- ---- oversight (Assembly members, auditors): summaries, and named officers only where entitled ----

create function public.oversight_overdue()
returns table (
  reference text, ward text, category text, department text, days_overdue int,
  escalation_level smallint, flagged_financial boolean, officer text, created_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select r.reference, w.name, c.name, d.name,
         greatest(0, floor(extract(epoch from (now() - r.resolve_due_at)) / 86400))::int,
         r.escalation_level, r.flagged_financial,
         -- named officer only for Assembly members and admins; auditors see the department
         case when private.has_role(array['assembly_member', 'admin', 'super_admin']) then p.name else null end,
         r.created_at
    from public.reports r
    join public.wards w on w.id = r.ward_id
    left join public.report_categories c on c.id = r.category_id
    left join public.departments d on d.id = r.department_id
    left join public.profiles p on p.id = r.assigned_to
   where private.has_role(array['assembly_member', 'auditor', 'admin', 'super_admin'])
     and r.status not in ('resolved', 'closed', 'rejected')
     and r.resolve_due_at < now()
   order by r.resolve_due_at asc;
$$;
grant execute on function public.oversight_overdue() to authenticated;

-- ---- ward alerts: draft -> pending -> approved by a second person ------------------

create function public.alert_submit(p_alert uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.alerts set status = 'pending_approval'
   where id = p_alert and created_by = (select auth.uid()) and status = 'draft';
  if not found then raise exception 'Alert not found or not a draft' using errcode = 'P0002'; end if;
end;
$$;

create function public.alert_approve(p_alert uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']) then
    raise exception 'Not allowed to approve alerts' using errcode = '42501';
  end if;
  update public.alerts
     set status = 'approved', approved_by = (select auth.uid()), approved_at = now()
   where id = p_alert and status = 'pending_approval' and created_by <> (select auth.uid());
  if not found then
    raise exception 'Alert not pending, or you wrote it (a second person must approve)' using errcode = '42501';
  end if;
end;
$$;
grant execute on function public.alert_submit(uuid), public.alert_approve(uuid) to authenticated;

-- ---- AI spend control ---------------------------------------------------------------

create table public.ai_budgets (
  id            uuid primary key default gen_random_uuid(),
  department_id uuid references public.departments (id),   -- null = county-wide default
  month         date not null,
  cap_kes       numeric(12, 2) not null check (cap_kes >= 0),
  unique nulls not distinct (department_id, month)
);

create table public.ai_calls (
  id            uuid primary key default gen_random_uuid(),
  at            timestamptz not null default now(),
  task          text not null,
  model         text not null,
  side          text not null check (side in ('citizen', 'county')),
  department_id uuid references public.departments (id),
  actor_id      uuid,
  tokens_in     int not null default 0,
  tokens_out    int not null default 0,
  cost_kes      numeric(12, 4) not null default 0,
  ok            boolean not null default true,
  redactions    int not null default 0
);
create index ai_calls_month_idx on public.ai_calls (department_id, at);

-- Month-to-date spend; the gateway refuses calls once a department reaches its cap.
create function private.ai_spend_mtd(p_department uuid)
returns numeric
language sql
stable
set search_path = ''
as $$
  select coalesce(sum(cost_kes), 0)
    from public.ai_calls
   where side = 'county'
     and department_id is not distinct from p_department
     and at >= date_trunc('month', now());
$$;
revoke execute on function private.ai_spend_mtd(uuid) from authenticated;
grant execute on function private.ai_spend_mtd(uuid) to service_role;

-- ---- oversight digests -------------------------------------------------------------------

create table public.digests (
  id           uuid primary key default gen_random_uuid(),
  kind         text not null check (kind in ('assembly', 'controller_of_budget', 'auditor_general', 'ward', 'department', 'executive')),
  period_start date not null,
  period_end   date not null,
  body_md      text not null,
  payload      jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  unique (kind, period_start, period_end)
);

create table public.digest_recipients (
  id          uuid primary key default gen_random_uuid(),
  digest_id   uuid not null references public.digests (id) on delete cascade,
  email       text not null,
  open_token  uuid not null default gen_random_uuid() unique,
  sent_at     timestamptz,
  first_opened_at timestamptz,
  open_count  int not null default 0
);

-- ---- RLS for operations tables -------------------------------------------------------------

alter table public.audit_log        enable row level security;
alter table public.ai_budgets       enable row level security;
alter table public.ai_calls         enable row level security;
alter table public.digests          enable row level security;
alter table public.digest_recipients enable row level security;

create policy "audit: read" on public.audit_log for select to authenticated
  using (private.has_role(array['super_admin', 'admin', 'auditor']));
revoke all on public.audit_log from anon, authenticated;
grant select on public.audit_log to authenticated;

create policy "ai budgets: admins" on public.ai_budgets for all to authenticated
  using (private.is_admin()) with check (private.is_admin());
create policy "ai calls: read" on public.ai_calls for select to authenticated
  using (private.has_role(array['super_admin', 'admin', 'auditor']));
revoke all on public.ai_budgets, public.ai_calls from anon, authenticated;
grant select, insert, update, delete on public.ai_budgets to authenticated;
grant select on public.ai_calls to authenticated;

create policy "digests: oversight read" on public.digests for select to authenticated
  using (private.has_role(array['super_admin', 'admin', 'assembly_member', 'auditor', 'chief_officer']));
revoke all on public.digests, public.digest_recipients from anon, authenticated;
grant select on public.digests to authenticated;

-- ==== 20260930000600_access_and_public_views.sql ====

-- 0006  Row-level security for civic + services tables, and the public read views.
-- Default is deny. Anonymous visitors see reference data, published projects, open tenders
-- and the aggregate views below. They never see a report row, a voter hash or a phone number.

-- ---- extra helpers -------------------------------------------------------------

-- May the signed-in user manage things in this ward (admin, its sub-county admin, its ward admin)?
create function private.can_manage_ward(p_ward text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.staff_roles r
    left join public.wards w on w.id = p_ward
    where r.user_id = (select auth.uid())
      and private.mfa_ok()
      and r.active
      and (r.expires_at is null or r.expires_at > now())
      and (
        r.role in ('super_admin', 'admin', 'chief_officer')
        or (r.role = 'sub_county_admin' and r.sub_county_id = w.sub_county_id)
        or (r.role = 'ward_admin'       and r.ward_id = p_ward)
      )
  );
$$;

-- May the signed-in user review applications for this service (admin, or officer/chief officer of its department)?
create function private.can_review_service(p_service uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.staff_roles r
    left join public.services s on s.id = p_service
    where r.user_id = (select auth.uid())
      and private.mfa_ok()
      and r.active
      and (r.expires_at is null or r.expires_at > now())
      and (
        r.role in ('super_admin', 'admin')
        or (r.role in ('chief_officer', 'officer') and r.department_id = s.department_id)
      )
  );
$$;

-- ---- enable RLS everywhere ------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array[
    'contractors', 'tenders', 'projects', 'project_milestones', 'project_photos',
    'budget_cycles', 'ward_budget_envelopes', 'project_options', 'votes',
    'reports', 'report_photos', 'report_events', 'routing_rules',
    'proposals', 'proposal_supports', 'alerts',
    'services', 'applications', 'application_documents', 'payments', 'revenue_entries', 'notifications'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;

-- ---- projects, tenders, contractors -----------------------------------------------

create policy "projects: public reads published" on public.projects for select to anon, authenticated
  using (published or private.is_staff());
create policy "projects: staff write" on public.projects for all to authenticated
  using (private.can_manage_ward(ward_id)) with check (private.can_manage_ward(ward_id));
grant select on public.projects to anon, authenticated;
grant insert, update, delete on public.projects to authenticated;

create policy "milestones: read with project" on public.project_milestones for select to anon, authenticated
  using (exists (select 1 from public.projects p where p.id = project_id));
create policy "milestones: staff write" on public.project_milestones for all to authenticated
  using (exists (select 1 from public.projects p where p.id = project_id and private.can_manage_ward(p.ward_id)))
  with check (exists (select 1 from public.projects p where p.id = project_id and private.can_manage_ward(p.ward_id)));
grant select on public.project_milestones to anon, authenticated;
grant insert, update, delete on public.project_milestones to authenticated;

create policy "photos: read with project" on public.project_photos for select to anon, authenticated
  using (exists (select 1 from public.projects p where p.id = project_id));
create policy "photos: staff write" on public.project_photos for all to authenticated
  using (exists (select 1 from public.projects p where p.id = project_id and private.can_manage_ward(p.ward_id)))
  with check (exists (select 1 from public.projects p where p.id = project_id and private.can_manage_ward(p.ward_id)));
grant select on public.project_photos to anon, authenticated;
grant insert, update, delete on public.project_photos to authenticated;

create policy "tenders: public reads non-draft" on public.tenders for select to anon, authenticated
  using (status <> 'draft' or private.is_staff());
create policy "tenders: staff write" on public.tenders for all to authenticated
